struct Message {
    Payload body;
    std::vector<std::function<void(Message&)>> slip;
    std::size_t cursor = 0;
};

void advance(Message& m) {
    while (m.cursor < m.slip.size()) m.slip[m.cursor++](m);
}
// planner: m.slip = {validate, reserve, charge};

task<void> advance(Message m) {
    for (auto& step : m.slip)
        co_await step.run(m);      // suspends, does not block the reactor
    co_await publish(std::move(m));
}
